import pytest

from app import is_adult


@pytest.mark.parametrize(
    "age, expected",
    [
        (0, False),
        (1, False),
        (17, False),
        (18, True),
        (19, True),
        (65, True),
    ],
)
def test_is_adult_returns_expected_boolean(age, expected):
    assert is_adult(age) is expected


@pytest.mark.parametrize("age", [-1, -18, -100])
def test_negative_age_raises_value_error(age):
    with pytest.raises(ValueError):
        is_adult(age)
